/* Browser validation of the staged public package, not native-device acceptance. */
const fs=require('node:fs'),path=require('node:path'),http=require('node:http'),assert=require('node:assert/strict'),pw=require('playwright'),{execFileSync}=require('node:child_process');
const engine=process.argv[2]||'chromium',root=path.resolve('app-dist'),out=path.resolve('qa-education-'+engine,'app');let browser,server,page,checks=0;const errors=[],external=[];function ok(v,m){assert.ok(v,m);checks++}
(async()=>{
 execFileSync(process.execPath,['scripts/stage-app.mjs']);fs.mkdirSync(out,{recursive:true});server=http.createServer((req,res)=>{const u=new URL(req.url,'http://localhost'),f=path.resolve(root,'.'+(u.pathname==='/'?'/index.html':u.pathname));if(!f.startsWith(root+path.sep)||!fs.existsSync(f)||!fs.statSync(f).isFile())return res.writeHead(404).end();res.setHeader('Content-Type',({'.js':'application/javascript','.html':'text/html','.css':'text/css','.png':'image/png','.webmanifest':'application/manifest+json'})[path.extname(f)]||'application/octet-stream');res.end(fs.readFileSync(f))});await new Promise(r=>server.listen(0,'127.0.0.1',r));const base='http://127.0.0.1:'+server.address().port;
 browser=await pw[engine].launch();const context=await browser.newContext({viewport:{width:1440,height:900}});page=await context.newPage();page.on('pageerror',e=>errors.push(e.message));page.on('request',r=>{if(!r.url().startsWith(base)&&!r.url().startsWith('data:')&&!r.url().startsWith('blob:'))external.push(r.url())});await page.goto(base+'/index.html');await page.waitForFunction(()=>!!window.__marineToolsOpenPage);ok(await page.locator('body').textContent().then(t=>t.includes('Live AIS/weather disabled')),'Prototype explicitly identified');
 await page.locator('#mtReleaseDialog[open] #mtReleaseDone').click();
 await page.evaluate(()=>__marineToolsOpenPage('vessel-calcs'));await page.locator('#calcAirDraft').click();ok(/3[.,]20 m remaining clearance/.test(await page.locator('#resAirDraft').textContent()),'Independent clearance: 25 - 0.8 - 20 - 1 = 3.20 m');
 await page.evaluate(()=>__marineToolsOpenPage('electrical'));await page.locator('#calc3p').click();ok(!/NaN|Infinity/.test(await page.locator('#res3p').textContent()),'Local electrical calculator renders');
 await page.evaluate(async()=>{await navigator.serviceWorker.ready;if(!navigator.serviceWorker.controller)await new Promise(r=>navigator.serviceWorker.addEventListener('controllerchange',r,{once:true}))});
 const cached=await page.evaluate(async()=>{const keys=await caches.keys();return (await Promise.all(keys.map(async k=>(await(await caches.open(k)).keys()).map(r=>r.url)))).flat()});ok(cached.some(u=>u.endsWith('/index.html')),'Public PWA shell cached');ok(!cached.some(u=>u.includes('/students/')),'Protected Education absent from cache');
 ok(await page.evaluate(async()=>(await caches.keys()).some(k=>/^marine-tools-app-preview-0\.1\.0-[a-f0-9]{16}$/.test(k))),'Offline package cache is versioned by asset contents');
 // A stopped server proves the cache works without relying on emulated network state.
 server.closeAllConnections();await new Promise(r=>server.close(r));server=null;await page.evaluate(()=>window.__beforeOfflineNavigation=true);let offlineNavigationError='';await page.goto(base+'/index.html?offline-check=1').catch(e=>{offlineNavigationError=e.message});await page.waitForFunction(()=>window.MT_APP_PREVIEW&&!window.__beforeOfflineNavigation&&!!window.__marineToolsOpenPage&&document.readyState==='complete');await page.evaluate(()=>__marineToolsOpenPage('vessel-calcs'));await page.locator('#calcAirDraft').click();ok(/3[.,]20 m remaining clearance/.test(await page.locator('#resAirDraft').textContent()),'Fresh offline navigation retains working calculator');
 await context.setOffline(true);await page.setViewportSize({width:390,height:844});ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+2),'Mobile package fits screen');await page.screenshot({path:path.join(out,'offline-mobile.png'),fullPage:true});
 ok(!external.some(u=>/api\.marinetools\.app|cloudflareinsights|google-analytics|offline-app\.invalid/.test(u)),'CSP prevents production/live network requests');ok(errors.length===0,'No package runtime exceptions: '+errors.join('; '));fs.writeFileSync(path.join(out,'results.json'),JSON.stringify({status:'PASS',engine,checks,errors,offlineNavigationError,externalRequests:external},null,2));console.log(JSON.stringify({status:'PASS',engine,checks}));
})().catch(async e=>{console.error(e);if(page){try{const d=await page.evaluate(async()=>({url:location.href,ready:document.readyState,title:document.title,body:document.body?.innerText.slice(0,3000),scripts:[...document.scripts].map(s=>s.src),app:!!window.MT_APP_PREVIEW,api:typeof window.__marineToolsOpenPage,caches:await caches.keys()}));console.error(JSON.stringify(d));fs.writeFileSync(path.join(out,'failure.json'),JSON.stringify({error:e.message,errors,diagnostics:d},null,2));await page.screenshot({path:path.join(out,'failure.png'),fullPage:true})}catch{}}process.exitCode=1}).finally(async()=>{await browser?.close();server?.close()});
